def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = [c for c in range(10) if c != background and any(c in row for row in grid)]

    # Prefix sums let us score every possible rectangle efficiently.
    pref = {}
    for color in colors:
        p = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            for c in range(w):
                p[r + 1][c + 1] = (
                    p[r][c + 1] + p[r + 1][c] - p[r][c]
                    + (grid[r][c] == color)
                )
        pref[color] = p

    candidates = []
    for color, p in pref.items():
        for r0 in range(h - 1):
            for r1 in range(r0 + 1, h):
                for c0 in range(w - 1):
                    for c1 in range(c0 + 1, w):
                        area = (r1 - r0 + 1) * (c1 - c0 + 1)
                        count = (p[r1 + 1][c1 + 1] - p[r0][c1 + 1]
                                 - p[r1 + 1][c0] + p[r0][c0])
                        if count * 4 >= area * 3:
                            score = count - 0.8 * (area - count)
                            candidates.append((score, count, color, r0, r1, c0, c1))

    candidates.sort(reverse=True)
    out = [[background] * w for _ in range(h)]
    for _, _, color, r0, r1, c0, c1 in candidates:
        # Don't let a candidate overwrite a stronger rectangle of another color.
        if any(out[r][c] not in (background, color)
               for r in range(r0, r1 + 1)
               for c in range(c0, c1 + 1)):
            continue
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color

    return out
